
module aes_mmio (
    input wire clk,
    input wire reset,

    input wire write_enable,
    input wire [31:0] address,
    input wire [31:0] write_data,

    output reg [31:0] read_data
);

    reg [127:0] plaintext_reg;
    reg [127:0] key_reg;

    wire [127:0] ciphertext;
    wire aes_busy;
    wire aes_done;

    // Start pulse generated by a control-register write
    wire aes_start =
        write_enable &&
        (address == 32'h00001020) &&
        write_data[0];

    // Store plaintext and key words
    always @(posedge clk) begin
        if (reset) begin
            plaintext_reg <= 128'b0;
            key_reg       <= 128'b0;
        end
        else if (write_enable) begin
            case (address)

                32'h00001000: plaintext_reg[127:96] <= write_data;
                32'h00001004: plaintext_reg[95:64]  <= write_data;
                32'h00001008: plaintext_reg[63:32]  <= write_data;
                32'h0000100C: plaintext_reg[31:0]   <= write_data;

                32'h00001010: key_reg[127:96] <= write_data;
                32'h00001014: key_reg[95:64]  <= write_data;
                32'h00001018: key_reg[63:32]  <= write_data;
                32'h0000101C: key_reg[31:0]   <= write_data;

                default: begin
                end

            endcase
        end
    end

    // AES-128 hardware accelerator
    aes128_seq aes_core (
        .clk(clk),
        .reset(reset),
        .start(aes_start),
        .plaintext(plaintext_reg),
        .key(key_reg),
        .ciphertext(ciphertext),
        .busy(aes_busy),
        .done(aes_done)
    );

    // Memory-mapped read interface
    always @(*) begin

        read_data = 32'b0;

        case (address)

            // Status
            32'h00001024:
                read_data = {30'b0, aes_done, aes_busy};

            // Ciphertext
            32'h00001028:
                read_data = ciphertext[127:96];

            32'h0000102C:
                read_data = ciphertext[95:64];

            32'h00001030:
                read_data = ciphertext[63:32];

            32'h00001034:
                read_data = ciphertext[31:0];

            default:
                read_data = 32'b0;

        endcase
    end

endmodule
